<?php
$pending = query('SELECT p.*,u.username,u.auto_approve FROM uploads p JOIN users u ON u.id=p.user_id WHERE p.approved=0 ORDER BY p.id')->fetchAll();
$members = query('SELECT id,username,role,disabled,auto_approve,created,last_login,last_seen,login_count FROM users ORDER BY created DESC LIMIT 8')->fetchAll();
$events = query('SELECT a.*,u.username FROM activity a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 8')->fetchAll();
